  name  String
  books LabL13Book[]
  @@map("lab_l13_authors")
}

model LabL13Book {
  id       Int          @id @default(autoincrement())
  title    String
  authorId Int          @map("author_id")
  author   LabL13Author @relation(fields: [authorId], references: [id])
  @@index([authorId])
  @@map("lab_l13_books")
}

